/**
 * یک آیکون به شکل رشتهٔ SVG.
 *
 * @param {string} name
 * @param {number} [size]
 * @param {string} [cls]
 */
export function iconSvg( name, size = 16, cls = '' ) {
	const def = ICONS[ name ];
	if ( ! def ) {
		return '';
	}
	const [ box, ...paths ] = def;
	return (
		`<svg class="ic ${ cls }" viewBox="${ box }" width="${ size }" height="${ size }" fill="currentColor" aria-hidden="true" focusable="false">` +
		paths.map( ( d ) => `<path d="${ d }" />` ).join( '' ) +
		'</svg>'
	);
}

/**
 * همان آیکون، ولی به شکل یک المان آمادهٔ appendChild.
 *
 * @param {string} name
 * @param {number} [size]
 * @param {string} [cls]
 */
export function icon( name, size = 16, cls = '' ) {
	const span = document.createElement( 'span' );
	span.className = `ico ${ cls }`.trim();
	span.innerHTML = iconSvg( name, size );
	return span;
}
